package ar.com.crivelli.facturas.service;
import ar.com.crivelli.facturas.model.*; import ar.com.crivelli.facturas.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class FacturaServiceTest { @Mock FacturaRepository facturas; @Mock ProveedorRepository proveedores; @InjectMocks FacturaService service;
 @Test void creaFacturaPendiente(){Proveedor p=new Proveedor("Transportes"); Factura f=new Factura(); f.setImporte(new BigDecimal("8500000")); when(proveedores.findById(1L)).thenReturn(Optional.of(p)); when(facturas.save(any())).thenAnswer(i->i.getArgument(0)); Factura r=service.crear(1L,f); assertEquals(EstadoFactura.PENDIENTE,r.getEstado()); assertEquals("GERENCIA",r.getNivelAprobacion());}
 @Test void montoSuperiorRequiereDireccion(){Factura f=new Factura(); f.setImporte(new BigDecimal("12500000")); assertEquals("DIRECCION",f.getNivelAprobacion());}
 @Test void noPermiteEvaluarDosVeces(){Factura f=new Factura(); f.setEstado(EstadoFactura.APROBADA); when(facturas.findById(1L)).thenReturn(Optional.of(f)); assertThrows(IllegalStateException.class,()->service.cambiarEstado(1L,EstadoFactura.RECHAZADA));}}
